/// A generated source file.
#[derive(Clone, Eq, PartialEq, Hash, Debug)]
pub struct GeneratedFile {
    /// The file path, relative to the generated source folder. (ex: `a/b/foo.rs`)
    pub path: String,

    /// The source code.
    pub code: String,
}

impl GeneratedFile {
    //! Constants

    /// The text in the first line of every generated file.
    pub const MARKER: &str = "DO NOT EDIT: This file was generated by the ProtoPacket compiler.";
}
